Lemma filled_updZ : forall c bs Q (i : Z) k,
  filled c bs Q -> (0 <= i)%Z -> (Z.to_nat i + k <= length bs)%nat ->
  filled c (upd_bytes bs (Z.to_nat i) (repeat c k)) (fun j => Q j \/ (i <= j < i + Z.of_nat k)%Z).
