  copied src bs (Z.to_nat P) -> (0 <= P)%Z -> firstn (length xs) (skipn (Z.to_nat P) src) = xs ->
  (Z.to_nat P + length xs <= length src)%nat ->
  copied src (upd_bytes bs (Z.to_nat P) xs) (Z.to_nat (P + Z.of_nat (length xs))).
