Lemma window_sub : forall (l xs : list byte) (base : Z) (k c j : nat) (i : Z),
  firstn k (skipn (Z.to_nat base) l) = xs -> (0 <= base)%Z -> (c + j <= k)%nat -> i = base + Z.of_nat c ->
  firstn j (skipn (Z.to_nat i) l) = firstn j (skipn c xs).
Proof.
